    }
    if (ci === r) {
      stripGroup.text('x')
        .move(cx + cellSize/2, topY + cellSize/2 + (state.showValues ? 0 : 0))
        .font({ size: Math.min(18, cellSize * 0.42), family: "'Times New Roman',serif", style: 'italic' })
        .attr({ 'text-anchor': 'middle', 'dominant-baseline': 'central' })
        .fill(state.showValues ? '#555' : '#000');
      if (state.showValues) {
        stripGroup.text(String(arr[ci]))
          .move(cx + cellSize/2, topY + cellSize * 0.28)
          .font({ size: Math.min(11, cellSize * 0.26), family: 'sans-serif' })
          .attr({ 'text-anchor': 'middle', 'dominant-baseline': 'central' })
          .fill('#888');
      }
    }
  }

  // Bars
  function drawBar(bx) {
    stripGroup.rect(barW, barH).move(bx - barW/2, barY).fill('#111');
  }
  if (i >= p - 1 && i < r) drawBar(leftX + (i + 1) * cellSize);
  if (j > p && j <= r) drawBar(leftX + j * cellSize);
  if (r > p) drawBar(leftX + r * cellSize);

  // Labels
  var labelY = topY - 20;
  var lf = { size: 18, family: "'Times New Roman',serif", style: 'italic' };
  stripGroup.text('p').move(leftX + p * cellSize + cellSize/2, labelY).font(lf).attr({'text-anchor':'middle'});
  if (i >= p - 1) stripGroup.text('i').move(leftX + (i+1)*cellSize, labelY).font(lf).attr({'text-anchor':'middle'});
  if (j <= r) stripGroup.text('j').move(leftX + j*cellSize, labelY).font(lf).attr({'text-anchor':'middle'});
  stripGroup.text('r').move(leftX + r*cellSize, labelY).font(lf).attr({'text-anchor':'middle'});

  // Braces
  var braceY = topY + cellSize + 14;
  var braceD = 13;
  var braceLabelY = braceY + braceD + 20;
  var bf = { size: 15, family: "'Times New Roman',serif" };

  if (i >= p) {
    var bx1 = leftX + p*cellSize, bx2 = leftX + (i+1)*cellSize;
    drawBrace(bx1, bx2, braceY, braceD);
    stripGroup.text('≤ x').move((bx1+bx2)/2, braceLabelY).font(bf).attr({'text-anchor':'middle'});
  }
  if (j - 1 > i) {
    var bx1 = leftX + (i+1)*cellSize, bx2 = leftX + j*cellSize;
    drawBrace(bx1, bx2, braceY, braceD);
    stripGroup.text('> x').move((bx1+bx2)/2, braceLabelY).font(bf).attr({'text-anchor':'middle'});
  }
  if (r - 1 >= j) {
    var bx1 = leftX + j*cellSize, bx2 = leftX + r*cellSize;
    drawBrace(bx1, bx2, braceY, braceD);
    stripGroup.text('unrestricted').move((bx1+bx2)/2, braceLabelY).font(bf).attr({'text-anchor':'middle'});
  }
}

function drawBrace(x1, x2, y, d) {
  var w = x2 - x1;
  if (w < 8) return;
  var s = 'M '+x1+','+y+
    ' C '+x1+','+(y+d*0.5)+' '+(x1+w*0.12)+','+(y+d*0.5)+' '+(x1+w*0.18)+','+(y+d)+
    ' L '+(x1+w*0.42)+','+(y+d)+
    ' C '+(x1+w*0.47)+','+(y+d)+' '+(x1+w*0.5)+','+(y+d*1.35)+' '+(x1+w*0.5)+','+(y+d*1.35)+
    ' C '+(x1+w*0.5)+','+(y+d*1.35)+' '+(x1+w*0.53)+','+(y+d)+' '+(x1+w*0.58)+','+(y+d)+
    ' L '+(x1+w*0.82)+','+(y+d)+
    ' C '+(x1+w*0.88)+','+(y+d*0.5)+' '+x2+','+(y+d*0.5)+' '+x2+','+y;
  stripGroup.path(s).fill('none').stroke({color:'#333',width:1.5});
}

function showDefaultStatic() {
  frames = []; frameIdx = -1;
  document.getElementById('playback').style.display = 'none';
  document.getElementById('statusReadout').textContent = '';
  document.getElementById('frameCaption').textContent = '';
  renderStrip({ array: new Array(16).fill(0), p:0, i:3, j:10, r:15, x:null, showValues:false, highlight:[] });
}

function showFrame(idx) {
  if (!frames.length || idx < 0 || idx >= frames.length) return;
  frameIdx = idx;
  var f = frames[idx];
  var st = f.state;
  renderStrip({ array: st.array, p: st.p, i: st.i, j: st.j, r: st.r, x: st.x, showValues: true, highlight: f.indices });
  document.getElementById('frameCounter').textContent = (idx+1) + ' / ' + frames.length;
  document.getElementById('frameCaption').textContent = f.message;
}

function stopPlaying() {
  isPlaying = false;
  if (playTimer) { clearTimeout(playTimer); playTimer = null; }
  document.getElementById('playPauseBtn').textContent = '▶';
}

function frameFirst() { stopPlaying(); showFrame(0); }
function framePrev() { stopPlaying(); if (frameIdx > 0) showFrame(frameIdx - 1); }
function frameNext() { stopPlaying(); if (frameIdx < frames.length - 1) showFrame(frameIdx + 1); }
function framePlayPause() {
  if (isPlaying) { stopPlaying(); return; }
  if (!frames.length) return;
  isPlaying = true;
  document.getElementById('playPauseBtn').textContent = '⏸';
  function tick() {
    if (!isPlaying) return;
    if (frameIdx < frames.length - 1) { showFrame(frameIdx + 1); playTimer = setTimeout(tick, playSpeed); }
    else stopPlaying();
  }
  tick();
}

function parseArray(str) {
  var parts = str.split(',').map(function(s){ return parseInt(s.trim(), 10); });
  if (parts.some(isNaN) || parts.length < 2) return null;
  return parts;
}

function runCode() {
  stopPlaying();
  var arr = parseArray(document.getElementById('arrayInput').value);
  if (!arr) { document.getElementById('statusReadout').textContent = '⚠ Invalid array'; return; }
  var code = document.getElementById('partitionCodeCode').value;
  var btn = document.getElementById('runBtn');
  btn.disabled = true; btn.textContent = '⏳ Running…';
  document.getElementById('statusReadout').textContent = 'Running…';

  var workerFn = function() {
    self.onmessage = function(e) {
      var data = e.data;
      var code = data.code;
      var array = data.array.slice();
      var p = data.p;
      var r = data.r;
      var frames = [];
      var maxFrames = 500;
      var maxOps = 2000;
      var opCount = 0;
      var startTime = Date.now();
      var timeout = 2000;
      var i = p - 1;
      var j = p;
      var x = array[r];
      var vars = {};
      var returned = null;

      function pushFrame(kind, indices, message) {
        frames.push({ kind: kind, state: { array: array.slice(), p: p, r: r, i: i, j: j, x: x }, indices: indices || [], message: message || '' });
        if (frames.length > maxFrames) throw new Error('Too many frames (limit ' + maxFrames + ')');
      }
      function checkTimeout() {
        if (++opCount > maxOps) throw new Error('Too many operations (limit ' + maxOps + ')');
        if (Date.now() - startTime > timeout) throw new Error('Timeout after ' + timeout + 'ms');
      }
      function apiCompare(idx, pivot) {
        checkTimeout();
        idx = Math.round(idx);
        if (idx < 0 || idx > r) throw new Error('compare: index ' + idx + ' out of bounds [0,' + r + ']');
        var result = array[idx] <= pivot;
        pushFrame('compare', [idx], 'compare(j=' + idx + ', x=' + pivot + '): A[' + idx + ']=' + array[idx] + ' ≤ ' + pivot + ' → ' + result);
        return result;
      }
      function apiSwap(a, b) {
        checkTimeout();
        a = Math.round(a); b = Math.round(b);
        if (a < 0 || a > r || b < 0 || b > r) throw new Error('swap: index out of bounds [' + a + ',' + b + ']');
        var tmp = array[a]; array[a] = array[b]; array[b] = tmp;
        pushFrame('swap', [a, b], 'swap(' + a + ', ' + b + '): A[' + a + '] ↔ A[' + b + ']');
      }
      function apiNote(text) { pushFrame('note', [], String(text)); }

      function evalExpr(expr) {
        expr = String(expr).trim();
        var m = expr.match(/^A\[([^\]]+)\]$/);
        if (m) { var idx = Math.round(evalExpr(m[1])); if (idx < 0 || idx >= array.length) throw new Error('Index ' + idx + ' out of bounds'); return array[idx]; }
        if (/^-?\d+$/.test(expr)) return parseInt(expr, 10);
        if (expr === 'i') return i;
        if (expr === 'j') return j;
        if (expr === 'x') return x;
        if (expr === 'p') return p;
        if (expr === 'r') return r;
        if (expr in vars) return vars[expr];
        var replaced = expr.replace(/A\[([^\]]+)\]/g, function(mm, inner) {
          var idx2 = Math.round(evalExpr(inner));
          if (idx2 < 0 || idx2 >= array.length) throw new Error('Index ' + idx2 + ' out of bounds');
          return '(' + array[idx2] + ')';
        });
        replaced = replaced.replace(/\b(i|j|x|p|r)\b/g, function(mm) {
          if (mm === 'i') return '(' + i + ')';
          if (mm === 'j') return '(' + j + ')';
          if (mm === 'x') return '(' + x + ')';
          if (mm === 'p') return '(' + p + ')';
          if (mm === 'r') return '(' + r + ')';
          return '(' + (vars[mm] !== undefined ? vars[mm] : 0) + ')';
        });
        replaced = replaced.replace(/\b([a-zA-Z_]\w*)\b/g, function(mm) {
          if (mm in vars) return '(' + vars[mm] + ')';
          throw new Error('Unknown variable: ' + mm);
        });
        try { return Function('return (' + replaced + ')')(); }
        catch(e2) { throw new Error('Cannot evaluate: ' + expr); }
      }

      var lines = code.split('\n');
      var cleanLines = [];
      for (var li = 0; li < lines.length; li++) {
        var lt = lines[li].replace(/\t/g, '  ');
        if (lt.trim() === '' || lt.trim().charAt(0) === '#') continue;
        cleanLines.push(lt);
      }
      function getIndent(line) { var m2 = line.match(/^ */); return m2 ? m2[0].length : 0; }
      var bodyStart = 0;
      for (var li2 = 0; li2 < cleanLines.length; li2++) {
        if (/^\s*PARTITION/.test(cleanLines[li2])) { bodyStart = li2 + 1; break; }
      }
      if (cleanLines.length === 0) throw new Error('Empty code');
      var baseIndent = getIndent(cleanLines[bodyStart] || '');

      function execBlock(start, end, indent) {
        var li3 = start;
        while (li3 < end) {
          var line = cleanLines[li3];
          var ind = getIndent(line);
          if (ind < indent) break;
          if (ind > indent) { li3++; continue; }
          var trimmed = line.trim();
          var fm = trimmed.match(/^for\s+(\w+)\s*=\s*(.+)\s+to\s+(.+):$/);
          if (fm) {
            var loopVar = fm[1], fromV = Math.round(evalExpr(fm[2])), toV = Math.round(evalExpr(fm[3]));
            var bEnd = li3 + 1;
            while (bEnd < end && getIndent(cleanLines[bEnd]) > ind) bEnd++;
            for (var v = fromV; v <= toV; v++) {
              checkTimeout();
              if (loopVar === 'j') j = v; else if (loopVar === 'i') i = v; else if (loopVar === 'x') x = v; else if (loopVar === 'p') p = v; else if (loopVar === 'r') r = v; else vars[loopVar] = v;
              execBlock(li3 + 1, bEnd, ind + 2);
            }
            li3 = bEnd; continue;
          }
          var im = trimmed.match(/^if\s+(.+):$/);
          if (im) {
            var condExpr = im[1].trim(); var condResult = false;
            var cm = condExpr.match(/^compare\((.+),\s*(.+)\)$/);
            if (cm) { condResult = apiCompare(evalExpr(cm[1]), evalExpr(cm[2])); }
            else { condResult = evalExpr(condExpr) !== 0; }
            var bEnd2 = li3 + 1;
            while (bEnd2 < end && getIndent(cleanLines[bEnd2]) > ind) bEnd2++;
            if (condResult) execBlock(li3 + 1, bEnd2, ind + 2);
            li3 = bEnd2; continue;
          }
          var sm = trimmed.match(/^swap\((.+),\s*(.+)\)$/);
          if (sm) { apiSwap(evalExpr(sm[1]), evalExpr(sm[2])); li3++; continue; }
          var nm = trimmed.match(/^note\((.+)\)$/);
          if (nm) {
            var na = nm[1].trim();
            if (na.charAt(0) === '"' || na.charAt(0) === "'") apiNote(na.slice(1, -1));
            else apiNote(evalExpr(na));
            li3++; continue;
          }
          var rm = trimmed.match(/^return\s+(.+)$/);
          if (rm) { returned = evalExpr(rm[1]); li3++; continue; }
          var am = trimmed.match(/^(\w+)\s*=\s*(.+)$/);
          if (am) {
            var vn = am[1], vv = evalExpr(am[2]);
            if (vn === 'i') i = vv; else if (vn === 'j') j = vv; else if (vn === 'x') x = vv; else if (vn === 'p') p = vv; else if (vn === 'r') r = vv; else vars[vn] = vv;
            li3++; continue;
          }
          li3++;
        }
      }

      try {
        pushFrame('init', [], 'Initial: i = p−1 = ' + i + ', j = p = ' + j + ', pivot x = A[' + r + '] = ' + x);
        execBlock(bodyStart, cleanLines.length, baseIndent);
        pushFrame('done', [], 'PARTITION complete. Returned q = ' + returned);
        self.postMessage({ ok: true, frames: frames, returned: returned, finalArray: array.slice() });
      } catch(err) {
        pushFrame('error', [], 'ERROR: ' + err.message);
        self.postMessage({ ok: false, frames: frames, error: err.message });
      }
    };
  };

  var blob = new Blob(['(' + workerFn.toString() + ')()'], { type: 'text/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  worker.onmessage = function(e) {
    URL.revokeObjectURL(url);
    worker.terminate();
    btn.disabled = false; btn.textContent = '▶ Run';
    var res = e.data;
    frames = res.frames || [];
    document.getElementById('playback').style.display = frames.length ? '' : 'none';
    if (frames.length) showFrame(0);

    if (!res.ok) {
      document.getElementById('statusReadout').textContent = '❌ Error: ' + (res.error || 'unknown');
      document.getElementById('statusReadout').style.color = '#c00';
      return;
    }
    // Success check
    var q = res.returned;
    var fa = res.finalArray;
    var pivot = fa[data_r];
    var ok = true;
    if (q === null || q === undefined || q < data_p || q > data_r) ok = false;
    else {
      if (fa[q] !== pivot) ok = false;
      for (var k = data_p; k < q; k++) { if (fa[k] > pivot) { ok = false; break; } }
      for (var k2 = q + 1; k2 <= data_r; k2++) { if (fa[k2] <= pivot) { ok = false; break; } }
    }
    if (ok) {
      document.getElementById('statusReadout').textContent = '✓ Correct! Pivot seated at q=' + q;
      document.getElementById('statusReadout').style.color = '#2e7d32';
    } else {
      document.getElementById('statusReadout').textContent = '✗ Wrong: invariant violated';
      document.getElementById('statusReadout').style.color = '#c00';
    }
  };
  worker.onerror = function(e) {
    URL.revokeObjectURL(url);
    worker.terminate();
    btn.disabled = false; btn.textContent = '▶ Run';
    document.getElementById('statusReadout').textContent = '❌ ' + e.message;
    document.getElementById('statusReadout').style.color = '#c00';
  };
  var data_p = 0, data_r = arr.length - 1;
  worker.postMessage({ code: code, array: arr, p: data_p, r: data_r });
}

function setTab(tab) {
  currentTab = tab;
  var ta = document.getElementById('partitionCodeCode');
  if (tab === 'sample') ta.value = SAMPLE_CODE;
  else if (tab === 'buggy') ta.value = BUGGY_CODE;
  else ta.value = STARTER_CODE;
  document.getElementById('tabSample').className = tab === 'sample' ? 'active' : '';
  document.getElementById('tabBuggy').className = tab === 'buggy' ? 'active' : '';
  document.getElementById('tabStarter').className = tab === 'starter' ? 'active' : '';
}

function toggle_nextBranchCase(on) {
  document.getElementById('arrayInput').value = on ? SKIP_ARRAY : SWAP_ARRAY;
  stopPlaying(); frames = []; frameIdx = -1;
  document.getElementById('playback').style.display = 'none';
  document.getElementById('statusReadout').textContent = '';
  var arr = parseArray(document.getElementById('arrayInput').value);
  if (arr) {
    renderStrip({ array: arr, p: 0, i: -1, j: 0, r: arr.length - 1, x: arr[arr.length-1], showValues: true, highlight: [] });
  }
}

function updateStep() {
  var s = demoSteps[demoStep];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (demoStep + 1) + '/' + demoSteps.length + ' ' + s.title;
  if (demoStep === 0) {
    document.getElementById('nextBranchCaseInput').checked = false;
    document.getElementById('arrayInput').value = SWAP_ARRAY;
    showDefaultStatic();
  } else if (demoStep === 1) {
    document.getElementById('nextBranchCaseInput').checked = false;
    document.getElementById('arrayInput').value = SWAP_ARRAY;
    setTab('sample');
    toggle_nextBranchCase(false);
    setTimeout(function(){ runCode(); }, 100);
  } else if (demoStep === 2) {
    document.getElementById('nextBranchCaseInput').checked = true;
    document.getElementById('arrayInput').value = SKIP_ARRAY;
    setTab('sample');
    toggle_nextBranchCase(true);
    setTimeout(function(){ runCode(); }, 100);
  }
}
function prevStep() { if (demoStep > 0) { demoStep--; updateStep(); } }
function nextStep() { if (demoStep < demoSteps.length - 1) { demoStep++; updateStep(); } }

// Init
setTab('sample');
updateStep();
window.__markRendered();
// @FIGURE_CODE_END

